interface.definition:
a!localVariables(
  local!firstName,
  local!lastName,
  local!searchResult,
  local!selectedEmployee,
  {
    #"SYSTEM_SYSRULES_sideBySideLayout"(
      alignVertical: "MIDDLE",
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_textField"(
            labelPosition: "COLLAPSED",
            placeholder: "First Name",
            value: local!firstName,
            saveInto: local!firstName
          )
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_textField"(
            labelPosition: "COLLAPSED",
            placeholder: "Last Name",
            value: local!lastName,
            saveInto: local!lastName
          )
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          width: "MINIMIZE",
          item: #"SYSTEM_SYSRULES_ButtonArrayLayout"(
            marginBelow: "NONE",
            buttons: #"SYSTEM_SYSRULES_ButtonWidget"(
              label: "Search",
              disabled: if(
                len(local!firstName)>1,
                false,
                true
              ),
              value: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3446907"(
                searchFirstName:  local!firstName,
                searchLastName:  local!lastName
              ),
              saveInto: {
                local!searchResult,
                a!save(ri!nominee,null)
              }
            )
          )
        )
      }
    ),
    #"SYSTEM_SYSRULES_gridField_v1"(
      data: index(local!searchResult,"data",null),
      columns: {
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "First Name",
          sortField: "firstName",
          value: index(fv!row,"firstName",null)
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Middle Name",
          sortField: "middleName",
          value: index(fv!row,"middleName",null)
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Last Name",
          sortField: "lastName",
          value: index(fv!row,"lastName",null)
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Email",
          sortField: "email",
          value: index(fv!row,"email",null)
        )
      },
      instructions: "Select a user",
      selectable: true,
      selectionStyle: "ROW_HIGHLIGHT",
      selectionValue: local!selectedEmployee,
      selectionSaveInto: {
        a!save(local!selectedEmployee,index(save!value,length(save!value),null)),
        a!save(ri!nominee,index(fv!selectedRows,length(fv!selectedRows),null))
      }
    )
  }
)
